    sortBy: v.optional(
      v.union(
        v.literal("createdAt"),
        v.literal("updatedAt"),
        v.literal("lastMessageAt"),
        v.literal("messageCount"),
      ),
    ),
    sortOrder: v.optional(v.union(v.literal("asc"), v.literal("desc"))),
    includeMessages: v.optional(v.boolean()),
  }, handler: async (ctx, args) => {
